const items = $input.all();
const results = [];

// 获取 Webhook 原始消息
let originalMessage = "";
try {
  originalMessage = $("Webhook").first().json.body.message;
} catch (e) {
  originalMessage = "No message found";
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // 1. 检查二进制数据是否存在
  if (!item.binary || !item.binary.data) {
    continue;
  }

  try {
    // 2. 使用 this.helpers 而不是 $helpers
    // 这里的 'data' 必须对应 Webhook 节点传入的二进制字段名
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    const text = buffer.toString('utf8');

    // 3. 解析 FASTA
    const lines = text.split(/\r?\n/);
    const sequenceParts = [];

    for (const line of lines) {
      const trimmed = line.trim();
      // 跳过空行和描述行 (>)
      if (trimmed.length > 0 && !trimmed.startsWith(">")) {
        sequenceParts.push(trimmed);
      }
    }

    results.push({
      json: {
        parsed_sequence: sequenceParts.join(''),
        fileName: item.binary.data.fileName || "unknown",
        original_message: originalMessage
      }
    });

  } catch (error) {
    results.push({
      json: { 
        error: error.message, 
        status: "failed",
        fileName: item.binary.data.fileName || "unknown" 
      }
    });
  }
}

return results;

parameters.toolDescription:
Predict active sites and binding residues using EasIFA.
Input must be a JSON object using ONE of the following formats:
1. By ID: {"uniprot_id": "P12345"}
2. By Sequence: {"aa_sequence": "MKF..."}
3. By Sequence + Reaction: {"aa_sequence": "MKF...", "rxn_smiles": "CC(=O)O>>CC(=O)OC"}
The tool returns a formatted Markdown table listing residue indices, names, active types, and confidence scores.
